import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    """Return a positive desirability score for each candidate swath (numpy arrays, same length).
    dist_m: distance to candidate start (m); turn_deg: turning needed (deg); swath_len_m: candidate length (m);
    energy_left_frac: battery fraction left (scalar 0..1); depot_dist_m: distance from candidate end to depot (m);
    fits: 1.0 if the candidate fits in the remaining battery, else 0.0."""
    return 1.0 / (dist_m + 1.0)

import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    eps = np.finfo(float).tiny

    def nonnegative(x):
        return np.maximum(np.nan_to_num(
            np.asarray(x, dtype=float),
            nan=1e12, posinf=1e12, neginf=0.0
        ), 0.0)

    dist = nonnegative(dist_m)
    length = nonnegative(swath_len_m)
    depot = nonnegative(depot_dist_m)
    turn = np.clip(np.nan_to_num(
        np.asarray(turn_deg, dtype=float),
        nan=180.0, posinf=360.0, neginf=0.0
    ), 0.0, 360.0)
    fit = np.clip(np.nan_to_num(
        np.asarray(fits, dtype=float),
        nan=0.0, posinf=0.0, neginf=0.0
    ), 0.0, 1.0)
    battery = float(np.clip(np.nan_to_num(
        energy_left_frac, nan=0.0, posinf=1.0, neginf=0.0
    ), 0.0, 1.0))

    cost = np.log1p(dist) + 0.25 * np.log1p(length) + turn / 720.0
    score = np.exp(-cost)
    score *= 0.02 + 0.98 * fit

    urgency = np.clip((0.7 - battery) / 0.7, 0.0, 1.0)
    score *= np.exp(-0.8 * urgency * depot / (depot + 1000.0))

    return np.maximum(np.nan_to_num(
        score, nan=eps, posinf=1.0, neginf=eps
    ), eps)
